import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { apply, compose, diff, fromSteps, invert, movePosition, splice, toChars, toUnits, transform, wellFormed, type Delta } from "./delta";
import { randomDelta, rng, word } from "./test-util";

describe("the daemon's own cases", () => {
  // Generated by crates/tether-core/src/delta.rs (the_shared_cases_are_current).
  const cases = JSON.parse(readFileSync(new URL("../../../../crates/tether-core/testdata/delta-cases.json", import.meta.url), "utf8")) as {
    text: string;
    edit: Delta;
    applied: Delta;
    edit2: Delta;
    applied2: Delta;
    result: string;
  }[];

  it("has plenty of them", () => expect(cases.length).toBeGreaterThan(200));

  it("gives the same answers here, in UTF-16 units", () => {
    for (const c of cases) {
      const edit = toUnits(c.edit, c.text);
      const applied = toUnits(c.applied, c.text);
      const [edit2, applied2] = transform(edit, applied);
      const afterApplied = apply(applied, c.text)!;
      const afterEdit = apply(edit, c.text)!;
      expect(toChars(edit2, afterApplied), JSON.stringify(c)).toEqual(c.edit2);
      expect(toChars(applied2, afterEdit), JSON.stringify(c)).toEqual(c.applied2);
      expect(apply(edit2, afterApplied)).toBe(c.result);
      expect(apply(applied2, afterEdit)).toBe(c.result);
    }
  });
});

describe("deltas", () => {
  it("converge, compose and invert, whatever they are", () => {
    for (let seed = 1; seed <= 1500; seed++) {
      const r = rng(seed);
      const text = word(r, 14);
      const a = randomDelta(r, text);
      const b = randomDelta(r, text);
      const [a2, b2] = transform(a, b);
      const left = apply(a2, apply(b, text)!);
      expect(left).toBe(apply(b2, apply(a, text)!));
      expect(left).not.toBeNull();

      const afterA = apply(a, text)!;
      const next = randomDelta(r, afterA);
      const both = compose(a, next);
      expect(apply(both, text), `seed ${seed}`).toBe(apply(next, afterA));
      expect(fromSteps(both)).toEqual(both);

      expect(apply(invert(a, text), afterA)).toBe(text);
      expect(apply(toUnits(toChars(a, text), text), text)).toBe(afterA);
    }
  });

  it("refuses to reach past the end", () => {
    expect(apply([6, "x"], "hello")).toBeNull();
    expect(apply([4, -2], "hello")).toBeNull();
  });

  it("works out what the user did", () => {
    expect(diff("hello", "helllo", 4)).toEqual([3, "l"]); // typed after "hel"
    expect(diff("hello", "helllo", 5)).toEqual([4, "l"]);
    expect(diff("hello", "helo", 2)).toEqual([2, -1]);
    expect(diff("hello", "hello")).toEqual([]);
    expect(diff("", "abc")).toEqual(["abc"]);
    expect(diff("one two", "one 2", 5)).toEqual([4, "2", -3]);
  });

  it("never splits a character in two", () => {
    // These share half of a surrogate pair.
    const d = diff("a😀b", "a😁b", 3);
    expect(d).toEqual([1, "😁", -2]);
    for (let seed = 1; seed <= 500; seed++) {
      const r = rng(seed);
      const before = word(r, 10);
      const after = apply(randomDelta(r, before), before)!;
      const change = diff(before, after, r(after.length + 1));
      expect(apply(change, before)).toBe(after);
      for (const s of change) if (typeof s === "string") expect(wellFormed(s)).toBe(s);
      expect(apply(toUnits(toChars(change, before), before), before)).toBe(after);
    }
  });

  it("keeps the caret with the text around it", () => {
    expect(movePosition(splice(0, 0, "abc"), 5)).toBe(8); // inserted before
    expect(movePosition(splice(7, 0, "abc"), 5)).toBe(5); // after
    expect(movePosition(splice(5, 0, "abc"), 5)).toBe(5); // at the caret: it stays
    expect(movePosition(splice(5, 0, "abc"), 5, true)).toBe(8);
    expect(movePosition(splice(3, 4, ""), 5)).toBe(3); // what it was in is gone
    expect(movePosition(splice(0, 2, "x"), 5)).toBe(4);
    expect(movePosition([2, "x", -1, 4, -3], 20)).toBe(17);
  });

  it("replaces halves of characters, which cannot be sent", () => {
    expect(wellFormed("a\ud83d")).toBe("a�");
    expect(wellFormed("\ude00b")).toBe("�b");
    expect(wellFormed("😀")).toBe("😀");
  });
});
